const SampleSound& SampleBank::getSample(int index) noexcept {
    if (index < 0 || index >= kNumSamples) return kSampleSounds[0];
    return kSampleSounds[index];
}

const char* SampleBank::getSampleName(int index) noexcept {
    if (index < 0 || index >= kNumSamples) return kSampleSounds[0].name;
    return kSampleSounds[index].name;
}

